146			fmt.Fprintf(os.Stderr, "usage error: --%s is required\n", name)
147			os.Exit(2)
148		}
149		value, err := strconv.ParseInt(raw, 10, 64)
150		if err != nil {
151			fmt.Fprintf(os.Stderr, "usage error: --%s must be an int64: %v\n", name, err)
152			os.Exit(2)
153		}
154		return value
155	}
