1333	
1334		good, err := os.ReadFile(path)
1335		if err != nil {
1336			t.Fatal(err)
1337		}
1338		// mutate 以结构化改写构造损坏变体；index 标明出问题的票据下标（dave 是第 1 张）。
1339		mutate := func(fn func(p map[string]any)) []byte {
1340			var clone map[string]any
1341			if err := json.Unmarshal(good, &clone); err != nil {
1342				t.Fatal(err)
1343			}
1344			p := clone["vote_proposals"].(map[string]any)["gip-incomplete"].(map[string]any)
1345			fn(p)
1346			raw, err := json.MarshalIndent(clone, "", "  ")
1347			if err != nil {
1348				t.Fatal(err)
1349			}
1350			return append(raw, '\n')
1351		}
1352		// 第一张票（下标 0）与第二张票（下标 1）各覆盖若干字段，确保下标被正确报告。
1353		cases := map[string]struct {
1354			raw       []byte
1355			index     string
1356			field     string
1357			causeWord string
1358		}{
1359			"support missing on ballot 0": {
1360				mutate(func(p map[string]any) {
1361					delete(p["ballots"].([]any)[0].(map[string]any), "support")
1362				}), "ballot 0", "support", "missing",
1363			},
1364			"support null on ballot 0": {
1365				mutate(func(p map[string]any) {
1366					p["ballots"].([]any)[0].(map[string]any)["support"] = nil
1367				}), "ballot 0", "support", "null",
1368			},
1369			"support string not boolean": {
1370				mutate(func(p map[string]any) {
1371					p["ballots"].([]any)[0].(map[string]any)["support"] = "true"
1372				}), "ballot 0", "support", "wrong type",
1373			},
1374			"support number not boolean": {
1375				mutate(func(p map[string]any) {
1376					p["ballots"].([]any)[0].(map[string]any)["support"] = 1
1377				}), "ballot 0", "support", "wrong type",
1378			},
1379			"voted_at missing with zero window": {
1380				mutate(func(p map[string]any) {
1381					delete(p["ballots"].([]any)[0].(map[string]any), "voted_at")
1382				}), "ballot 0", "voted_at", "missing",
1383			},
1384			"voted_at null not timestamp zero": {
1385				mutate(func(p map[string]any) {
1386					p["ballots"].([]any)[0].(map[string]any)["voted_at"] = nil
1387				}), "ballot 0", "voted_at", "null",
1388			},
1389			"voted_at string not integer": {
1390				mutate(func(p map[string]any) {
1391					p["ballots"].([]any)[0].(map[string]any)["voted_at"] = "0"
1392				}), "ballot 0", "voted_at", "wrong type",
1393			},
1394			"voted_at float not integer": {
1395				mutate(func(p map[string]any) {
1396					p["ballots"].([]any)[0].(map[string]any)["voted_at"] = 150.5
1397				}), "ballot 0", "voted_at", "wrong type",
1398			},
1399			"weight null": {
1400				mutate(func(p map[string]any) {
1401					p["ballots"].([]any)[1].(map[string]any)["weight"] = nil
1402				}), "ballot 1", "weight", "null",
1403			},
1404			"weight missing": {
1405				mutate(func(p map[string]any) {
1406					delete(p["ballots"].([]any)[1].(map[string]any), "weight")
1407				}), "ballot 1", "weight", "missing",
1408			},
1409			"weight float not integer": {
1410				mutate(func(p map[string]any) {
1411					p["ballots"].([]any)[1].(map[string]any)["weight"] = 400.5
1412				}), "ballot 1", "weight", "wrong type",
1413			},
1414			"weight over int64": {
1415				mutate(func(p map[string]any) {
1416					p["ballots"].([]any)[1].(map[string]any)["weight"] = 9223372036854775808.0
1417				}), "ballot 1", "weight", "wrong type",
1418			},
1419			"representative null": {
1420				mutate(func(p map[string]any) {
1421					p["ballots"].([]any)[1].(map[string]any)["representative"] = nil
1422				}), "ballot 1", "representative", "null",
1423			},
1424			"representative missing": {
1425				mutate(func(p map[string]any) {
1426					delete(p["ballots"].([]any)[1].(map[string]any), "representative")
1427				}), "ballot 1", "representative", "missing",
1428			},
1429			"representative number not string": {
1430				mutate(func(p map[string]any) {
1431					p["ballots"].([]any)[1].(map[string]any)["representative"] = 7
1432				}), "ballot 1", "representative", "wrong type",
1433			},
1434			"support array not boolean": {
1435				mutate(func(p map[string]any) {
1436					p["ballots"].([]any)[0].(map[string]any)["support"] = []any{}
1437				}), "ballot 0", "support", "wrong type",
1438			},
1439		}
1440		for name, tc := range cases {
1441			t.Run(name, func(t *testing.T) {
1442				bad := filepath.Join(dir, "bad-"+strings.ReplaceAll(name, " ", "-")+".json")
1443				if err := os.WriteFile(bad, tc.raw, 0o600); err != nil {
1444					t.Fatal(err)
1445				}
1446	
1447				// 打开即拒绝，错误带提案编号、票据下标、字段与原因分类。
1448				s, err := Open(bad)
1449				if !errors.Is(err, ErrStateCorrupt) {
1450					if s != nil {
1451						s.Close()
1452					}
1453					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
1454				}
1455				msg := err.Error()
1456				for _, want := range []string{`"gip-incomplete"`, tc.index, `"` + tc.field + `"`, tc.causeWord} {
1457					if !strings.Contains(msg, want) {
1458						t.Fatalf("error %q missing %q", msg, want)
1459					}
1460				}
1461	
1462				// 原文件内容必须原样保留（失败不回写、不补默认值）。
1463				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(tc.raw) {
1464					t.Fatalf("corrupt file was modified on rejected Open")
1465				}
1466	
1467				// 重复打开仍以同一损坏分类拒绝，绝不返回可用句柄给出部分结果。
1468				s2, e := Open(bad)
1469				if !errors.Is(e, ErrStateCorrupt) {
1470					if s2 != nil {
1471						s2.Close()
1472					}
1473					t.Fatalf("reopen err=%v, want ErrStateCorrupt", e)
1474				}
1475			})
1476		}
1477	}
1478	
1479	// TestIncompleteBallotOpsRejectAndKeepFile：损坏文件上的查询与计票/投票操作
1480	// 一律返回 ErrStateCorrupt，且不产生部分结果、不改写文件、不动提案状态与余额。
1481	func TestIncompleteBallotOpsRejectAndKeepFile(t *testing.T) {
1482		dir := t.TempDir()
1483		path := filepath.Join(dir, "treasury.json")
1484		store, err := InitTreasury(path, 1000)
1485		if err != nil {
1486			t.Fatal(err)
1487		}
1488		in := baseVoteInput("gip-ops")
1489		in.StartAt, in.Deadline, in.TimelockEnd = 0, 200, 300
1490		mustCreateVote(t, store, in)
1491		if _, err := store.CastVote("gip-ops", "alice", true, 0); err != nil {
1492			t.Fatal(err)
1493		}
1494		mustRegister(t, store, "gip-spent", 0, "transfer:audits:100")
1495		if _, err := store.Execute("gip-spent", 0); err != nil {
1496			t.Fatal(err)
1497		}
1498		store.Close()
1499	
1500		good, err := os.ReadFile(path)
1501		if err != nil {
1502			t.Fatal(err)
1503		}
1504		var clone map[string]any
1505		if err := json.Unmarshal(good, &clone); err != nil {
1506			t.Fatal(err)
1507		}
1508		// 删除赞成票的 support 字段：若被默认成 false，600 赞成会被误算成 600 反对。
1509		delete(clone["vote_proposals"].(map[string]any)["gip-ops"].(map[string]any)["ballots"].([]any)[0].(map[string]any), "support")
1510		bad, err := json.MarshalIndent(clone, "", "  ")
1511		if err != nil {
1512			t.Fatal(err)
1513		}
1514		bad = append(bad, '\n')
1515		if err := os.WriteFile(path, bad, 0o600); err != nil {
1516			t.Fatal(err)
1517		}
1518	
1519		// 打开后，任何读取或操作都拒绝。
1520		s, err := Open(path)
1521		if !errors.Is(err, ErrStateCorrupt) {
1522			t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
1523		}
1524		if s != nil {
1525			t.Fatal("corrupt open must not return a usable store")
1526		}
1527	
1528		// 直接验证文件未被任何尝试改写。
1529		if got, rerr := os.ReadFile(path); rerr != nil || string(got) != string(bad) {
1530			t.Fatalf("corrupt file was normalized or rewritten")
1531		}
1532	
1533		// 用一个真实打开的句柄，随后在句柄之外把文件改坏，下一次读取/操作必须拒绝。
1534		recoverPath := filepath.Join(dir, "recover.json")
1535		if err := os.WriteFile(recoverPath, good, 0o600); err != nil {
1536			t.Fatal(err)
1537		}
1538		live, err := Open(recoverPath)
1539		if err != nil {
1540			t.Fatal(err)
1541		}
1542		defer live.Close()
1543		if bal, err := live.TreasuryBalance(); err != nil || bal != 900 {
1544			t.Fatalf("balance before corruption=%d err=%v", bal, err)
1545		}
1546		if err := os.WriteFile(recoverPath, bad, 0o600); err != nil {
1547			t.Fatal(err)
1548		}
1549		if _, err := live.TreasuryBalance(); !errors.Is(err, ErrStateCorrupt) {
1550			t.Fatalf("TreasuryBalance after corruption err=%v, want ErrStateCorrupt", err)
1551		}
1552		if _, _, err := live.VoteProposal("gip-ops"); !errors.Is(err, ErrStateCorrupt) {
1553			t.Fatalf("VoteProposal after corruption err=%v", err)
1554		}
1555		if _, err := live.VoteProposals(); !errors.Is(err, ErrStateCorrupt) {
1556			t.Fatalf("VoteProposals after corruption err=%v", err)
1557		}
1558		if _, err := live.ProposalsSnapshot(); !errors.Is(err, ErrStateCorrupt) {
1559			t.Fatalf("ProposalsSnapshot after corruption err=%v", err)
1560		}
1561		if _, err := live.TallyVote("gip-ops", 200); !errors.Is(err, ErrStateCorrupt) {
1562			t.Fatalf("TallyVote after corruption err=%v", err)
1563		}
1564		if _, err := live.CastVote("gip-ops", "dave", false, 150); !errors.Is(err, ErrStateCorrupt) {
1565			t.Fatalf("CastVote after corruption err=%v", err)
1566		}
1567		if _, err := live.BalanceSnapshot(); !errors.Is(err, ErrStateCorrupt) {
1568			t.Fatalf("BalanceSnapshot after corruption err=%v", err)
1569		}
1570		// 失败后文件字节、提案状态与余额保持损坏被发现时的原样（未回写默认值）。
1571		if got, rerr := os.ReadFile(recoverPath); rerr != nil || string(got) != string(bad) {
1572			t.Fatalf("failed ops rewrote or normalized the state file")
1573		}
1574	}
