		{"tally", "--id", "gip-cli-del", "--now", "10", "--json"},
		{"execute", "--id", "gip-cli-del", "--now", "10"},
		{"balances", "--json"},
	} {
		name := strings.Join(args, "_")
		t.Run(name, func(t *testing.T) {
